CHECKPOINT_IMPORT_RECONCILIATIONS_CURSOR = CursorKind(
    version=CHECKPOINT_IMPORT_RECONCILIATIONS_CURSOR_VERSION,
    claim_fields=("limit", "offset"),
    validate=_validate_checkpoint_import_reconciliations_claims,
